"""Self-contained coding tasks: prompt + pytest file. Pass = the test file passes. Same tasks for every arm."""
TASKS = [
 {"id": "roman", "file": "roman.py", "prompt": "Create roman.py with to_roman(n:int)->str for 1..3999 and from_roman(s:str)->int. Standard subtractive notation. from_roman raises ValueError on invalid numerals like 'IIII' or 'VX'.",
  "test": "import pytest\nfrom roman import to_roman, from_roman\ndef test_basic():\n    assert to_roman(1994)=='MCMXCIV' and to_roman(4)=='IV' and to_roman(3999)=='MMMCMXCIX'\n    assert from_roman('MCMXCIV')==1994\ndef test_roundtrip():\n    assert all(from_roman(to_roman(i))==i for i in range(1,4000))\n@pytest.mark.parametrize('bad',['IIII','VX','IC','','ABC'])\ndef test_invalid(bad):\n    with pytest.raises(ValueError): from_roman(bad)\n"},
 {"id": "lru", "file": "lru.py", "prompt": "Create lru.py with class LRUCache(capacity:int) having get(key)->value or None, put(key,value), and __len__. Evict the least recently used on overflow; both get and put count as use. capacity<=0 raises ValueError.",
  "test": "import pytest\nfrom lru import LRUCache\ndef test_evict():\n    c=LRUCache(2); c.put('a',1); c.put('b',2); assert c.get('a')==1; c.put('c',3)\n    assert c.get('b') is None and c.get('a')==1 and c.get('c')==3 and len(c)==2\ndef test_update_counts_as_use():\n    c=LRUCache(2); c.put('a',1); c.put('b',2); c.put('a',9); c.put('c',3)\n    assert c.get('a')==9 and c.get('b') is None\ndef test_bad():\n    with pytest.raises(ValueError): LRUCache(0)\n"},
 {"id": "duration", "file": "duration.py", "prompt": "Create duration.py with parse_duration(s:str)->int returning seconds. Accept units d,h,m,s with optional spaces and any order, e.g. '1h 30m', '2d4h', '45s', '90m'. Case-insensitive. Raise ValueError on empty, unknown units, or a number without a unit.",
  "test": "import pytest\nfrom duration import parse_duration as p\ndef test_ok():\n    assert p('1h 30m')==5400 and p('2d4h')==187200 and p('45s')==45 and p('90m')==5400 and p('1H')==3600\n@pytest.mark.parametrize('bad',['','5','5x','h','1h 5'])\ndef test_bad(bad):\n    with pytest.raises(ValueError): p(bad)\n"},
 {"id": "intervals", "file": "intervals.py", "prompt": "Create intervals.py with merge(intervals) taking a list of [start,end] pairs (ints, start<=end) and returning merged non-overlapping intervals sorted by start; touching intervals like [1,2],[2,3] merge. Do not mutate the input.",
  "test": "from intervals import merge\ndef test_merge():\n    assert merge([[8,10],[1,3],[2,6],[15,18]])==[[1,6],[8,10],[15,18]]\n    assert merge([[1,2],[2,3]])==[[1,3]] and merge([])==[] and merge([[5,5]])==[[5,5]]\ndef test_no_mutation():\n    a=[[3,4],[1,2]]; merge(a); assert a==[[3,4],[1,2]]\n"},
 {"id": "brackets", "file": "brackets.py", "prompt": "Create brackets.py with is_balanced(s:str)->bool for ()[]{} ignoring all other characters. Properly nested only; empty string is balanced.",
  "test": "from brackets import is_balanced as b\ndef test_all():\n    assert b('') and b('a(b)[c]{d}') and b('{[()]}') and b('no brackets')\n    assert not b('(]') and not b('(()') and not b('())') and not b('{[}]') and not b(')(')\n"},
 {"id": "flatten", "file": "flat.py", "prompt": "Create flat.py with flatten(d:dict, sep='.')->dict turning nested dicts into dotted keys ({'a':{'b':1}} -> {'a.b':1}) and unflatten(d, sep='.')->dict as the inverse. Lists are left as values. Empty nested dict becomes the value {} at that key.",
  "test": "from flat import flatten, unflatten\ndef test_flatten():\n    assert flatten({'a':{'b':1,'c':{'d':2}},'e':[1,2]})=={'a.b':1,'a.c.d':2,'e':[1,2]}\n    assert flatten({'a':{}})=={'a':{}} and flatten({'a':{'b':1}},sep='/')=={'a/b':1}\ndef test_inverse():\n    d={'a':{'b':1,'c':{'d':2}},'e':3}\n    assert unflatten(flatten(d))==d\n"},
 {"id": "wrap", "file": "wrap.py", "prompt": "Create wrap.py with wrap(text:str, width:int)->list[str] doing greedy word wrap: split on whitespace, never break a word unless it is longer than width (then split it into width-sized chunks), no trailing spaces, collapse runs of whitespace. width<1 raises ValueError.",
  "test": "import pytest\nfrom wrap import wrap\ndef test_wrap():\n    assert wrap('the quick brown fox jumps',10)==['the quick','brown fox','jumps']\n    assert wrap('a   b',3)==['a b'] and wrap('',5)==[]\n    assert wrap('abcdefghij',4)==['abcd','efgh','ij']\ndef test_bad():\n    with pytest.raises(ValueError): wrap('x',0)\n"},
 {"id": "csv", "file": "tinycsv.py", "prompt": "Create tinycsv.py with parse_line(line:str)->list[str] for one CSV line: comma separated, fields may be double-quoted, quoted fields may contain commas, and a doubled quote inside quotes is a literal quote. Unterminated quote raises ValueError. No csv module.",
  "test": "import pytest\nfrom tinycsv import parse_line as p\ndef test_ok():\n    assert p('a,b,c')==['a','b','c'] and p('a,\"b,c\",d')==['a','b,c','d']\n    assert p('\"he said \"\"hi\"\"\",x')==['he said \"hi\"','x'] and p('')==['']\n    assert p('a,,b')==['a','','b']\ndef test_bad():\n    with pytest.raises(ValueError): p('a,\"b')\n"},
]
